"""Summarize every allocated developmental run without selecting winners."""
import collections,datetime,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parent
s=json.loads((ROOT/'pilot/results-summary.json').read_text());m=json.loads((ROOT/'pilot/manifest.json').read_text());assert s['completed']==s['allocated']==len(m['allocations'])
assert {x['runId'] for x in s['runs']}=={x['runId'] for x in m['allocations']}
for r in s['runs']:
 d=json.loads((ROOT/'pilot/results'/(r['runId']+'.json')).read_text());assert d['materialSha256']==m['materialHashes'][d['arm']]
 rows=s['runs']
byModel={model['id']:{'family':model['family'],'successes':sum(r['acceptancePass'] for r in rows if r['model']==model['id']),'allocated':sum(a['model']==model['id'] for a in m['allocations'])} for model in m['models']}
byArm={arm:{'successes':sum(r['acceptancePass'] for r in rows if r['arm']==arm),'allocated':sum(a['arm']==arm for a in m['allocations']),'promptTokens':sum((r.get('usage') or {}).get('prompt_tokens',0) for r in rows if r['arm']==arm),'completionTokens':sum((r.get('usage') or {}).get('completion_tokens',0) for r in rows if r['arm']==arm),'runSeconds':sum(r['totalRunSeconds'] for r in rows if r['arm']==arm)} for arm in ['none','note','git','dxp']}
report={'id':'dxp-local-runner-status-20261016','updatedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'invocationVerified':True,'independentWeightFamilies':2,'models':m['models'],'developmentalExecutions':s['completed'],'confirmatoryExecutions':0,'materialDelivery':'Exactly assigned serialized payload injected into each model prompt; not tool retrieval or understanding.','evaluator':'Restricted QuickJS, no host callbacks, filesystem or network API; 7 positive/negative/isolation controls passed. No OS namespace claim.','byModel':byModel,'byArm':byArm,'setup':{'modelsDownloadedBytes':sum(x['bytes'] for x in m['models']),'modelLoads':s['modelLoads'],'costUSD':None,'costMeaning':'No paid API credit purchase or subscription upgrade. CPU/storage/energy value not measured; no claim of zero total cost or savings.'},'cloudRoute':{'catalogReachable':True,'catalogModels':60,'enabledModels':0,'reason':'paid_plan_required','creditsPurchased':False,'subscriptionChanged':False,'temporaryCredentialRevoked':True,'separateEmptyProject':'icy-brook-27441566'},'decision':'Local model invocation and bounded evaluation now work. This developmental matrix is not evidence of novel-task transfer or incremental DXP operations. If both small models fail all acceptances, the pilot has a capability floor and cannot distinguish memory benefits.','nextGate':'Improve model/task capability on unscored development work, implement actual controlled DXP/Git/flat operations, then freeze a separate unseen task matrix before confirmatory outputs.','limitations':m['limits']}
(ROOT/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
